// @ts-nocheck
import * as React from 'react';
import { List } from '@mui/material';
import CustomizedMenus from './DDmenu';

export default function LargerList(props: props) {

  if (!props.props[0]) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <List
        sx={{  paddingRight: "3%", width: '100%', bgcolor: 'background.paper' }}
        aria-labelledby="nested-list-subheader"
      >
        {props.props[0].map(item => (
            
                    <CustomizedMenus props = {[item, props.props[1]]}/>

        ))}

      </List>
    </div>


  );
}
