// @ts-nocheck


import * as React from 'react';
import Box from '@mui/material/Box';
import { DataGrid, GridColDef } from '@mui/x-data-grid';
import { useEffect, useState, useRef, useMemo } from 'react';
import Stack from '@mui/material/Stack';
const columns = [
  {
    field:'id'  ,
    headerName: 'Product Name',
    width: 400,
  },
  {
    field: 'Parent Company',
    headerName: 'Parent Company',
    width: 170,
  },
  {
    field: 'Length',
    headerName: 'Years Observed',
    type: 'number',
    width: 150,

  },
  {
    field: 'Price Diff',
    headerName: 'Change in Price',
    type: 'number',
    width: 110,
  },
  {
    field: 'Percent Increase/Yr',
    headerName: 'Percent Increase/Yr',
    type: 'number',
    width: 110,
  },
];


export default function Grid(props: props) {
    const [data2, setData] = useState(props.props[0]);



  const handleRowClick = (
      params, // GridRowParams
      event, // MuiEvent<React.MouseEvent<HTMLElement>>
      details, // GridCallbackDetails
    ) => {

      props.props[1].props([params['id'], params.row['Date'], params.row['Price'], params.row['New Price']])

    };

  const arrayColumn = (arr, n) => arr.map(x => x[n]);
  return (
    <Stack spacing={2} sx={{ width: '100%' }}>
    <Box sx={{ width: '100%' }}>
    <div style={{ display: 'flex', flexDirection: 'column' }}>
      
      <DataGrid
      sx={{
        boxShadow: 2,
        border: 2,
        "& .MuiDataGrid-row:hover": {
      backgroundColor: "#d5d1d1"
        // color: "red"
  },
  
        borderColor: 'primary.light',
  
      }}
      initialState={{
        pagination: {
          paginationModel: {
            pageSize: 5,
          },
        },
      }}
      onRowClick={handleRowClick}      
      rows = {data2}
      disableColumnMenu = {true}
        columns={columns}
        
        repaintChangesOnly={true}
        pageSizeOptions={[8]}
        
         />
         
      </div>

    </Box>
    </Stack>
  );
}