// @ts-nocheck
import * as React from 'react';
import { useRef } from 'react';
import { List, ListItemText, ListItem, ListItemIcon } from '@mui/material';
import ExpandLess from '@mui/icons-material/ExpandLess';
import ExpandMore from '@mui/icons-material/ExpandMore';
import Collapse from '@mui/material/Collapse';
import Divider from '@mui/material/Divider';
import NestedList from './ListItem';
export default function CustomizedMenus(props: props) {
  const [open, setOpen] = React.useState(false);

  const ref = useRef<HTMLInputElement>(null);
  const handleClick = (vals) => {
    setOpen(!open);
  };
  const scroll = (scrollOffset: number) => {
    let scrollAmount : number = document.documentElement.clientWidth * (SCROLL_BAR_WIDTH /100) * scrollOffset
    if (ref.current != null) {
      ref.current.scrollTo({
        left: ref.current.scrollLeft + scrollAmount,
        behavior: "smooth",
      })
    }
  };

  if (!props.props[0].PN) {
    return <div>Loading...</div>;
  }

  return (
    <div>
    <ListItem id={props.props[0].PC} onClick={() => handleClick(props.props[0].PC)}>
    <ListItemText primary={props.props[0].PC} sx={{ width: '90%' }} />
                              <ListItemIcon>
                                {open ? <ExpandLess /> : <ExpandMore />}
                              </ListItemIcon>
                            </ListItem>
                             <Divider sx={{ bgcolor: '#d1d8e1' }} />
                             <Collapse in={open} timeout="auto" unmountOnExit>
                             
                             <List
        sx={{ left: "3%", position:'relative',   bgcolor: 'background.paper' }}
        aria-labelledby="nested-list-subheader"
      >                  
                             {props.props[0].PN.map(item => (
          
          <NestedList props = {[item, props.props[1]]}/>
        ))}
              </List>
        </Collapse>


    </div>


  );
}
