// @ts-nocheck
import * as React from 'react';
import Tab from '@mui/material/Tab';
import Box from '@mui/material/Box';
import CustomizedMenus from './DDmenu';
import Tabs, { tabsClasses } from '@mui/material/Tabs';
import { useEffect, useState } from 'react';
import LargerList from './LargerListItem';
import SearchBar from './GraphStuff/SearchBar';
interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function CustomTabPanel(props: props) {

  const { children, value, index, ...other } = props;
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && <Box >{children}</Box>}
    </div>
  );
}



export default function BasicTabs(props: props) {
  console.log('IN HERE', props)
  const [data, setData] = useState(null);
  const [value, setValue] = React.useState(0);
  useEffect(() => {
      fetch('toBeUsed/productGeneralization.json')
      .then(response => response.json())
      .then(data => setData(data))
      .catch(error => console.error('Error fetching data:', error));
  }, []);


  function a11yProps(index: number) {
    return {
      id: `simple-tab-${index}`,
      'aria-controls': `simple-tabpanel-${index}`,
    };
  }


  const handleChange = (event: React.SyntheticEvent, newValue: number) => {
    setValue(newValue);
  };

  if (!data) {
    return <div>Loading...</div>;
  } 

  return (
    <Box sx={{ width: '100%'}}>
      <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
        <Tabs 
        sx={{
          [`& .${tabsClasses.scrollButtons}`]: {
            '&.Mui-disabled': { opacity: 0.3 },
          },
        }}
      
        variant="scrollable"  value={value} onChange={handleChange} aria-label="basic tabs example">
          <Tab sx={{ width: '10vw'}} label={'Product Categories'} {...a11yProps(value)} />
          <Tab sx={{ width: '10vw'}} label={'Search'} {...a11yProps(value)} />
          <Tab sx={{ width:  '10vw'}} label={'Parent Companies'} {...a11yProps(value)} />
        </Tabs>
      </Box>

        <CustomTabPanel value={value} index={0}>
          <LargerList props = {[data, props]}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={1}>
          <SearchBar props = {props.props}/>
        </CustomTabPanel>
        <CustomTabPanel value={value} index={2}>
          <LargerList props = {[data, props]}/>
        </CustomTabPanel>
      
    </Box>
  );
}

